\u0077\u0053\u0070\u0022\u0071\u002b\u0078\u0060\u0050\u0073\u0041\u0077\u0026\u0034\u006c\u004a\u0078\u0076\u0045\u006b\u0069\u004f\u0040\u0026\u0034\u0055\u0049\u004e\u0066\u007b\u004f\u007b\u0052\u003a\u0026\u002e\u0075\u0066\u0028\u0074\u0073\u0052\u0066\u0044\u005e\u0024\u0028\u0071\u0047\u0059\u0049\u0034\u005d\u0079\u0056\u002c\u0034\u006d\u0061\u0031\u0021\u004a\u0055\u0046\u0057\u0059\u0067\u004c\u007a\u0072\u0045\u0063\u0054\u005b\u0051\u0072\u0070\u0043\u003f\u0067\u0070\u003b\u0055\u0055\u0072\u0074\u003b\u0061\u004f\u0046\u007b\u0061\u0023\u0077\u002e\u0073\u007e\u007d\u0031\u0059\u0046\u0068\u0026\u0022\u0070\u0021\u002e\u0069\u0060\u0031\u005d\u006c\u0040\u0056\u0044\u0057\u0048\u003f\u002b\u0035\u003b\u005a\u0023\u006d\u0034\u0035\u006d\u0055\u0045\u0023\u0031\u0044\u0040\u0041\u0077\u0032\u0034\u002b\u006b\u0032\u0057\u0047\u0073\u0056\u0034\u0064\u003b\u0032\u0034\u0029\u004e\u0057\u0059\u0067\u004c\u007a\u0072\u0045\u007c\u003b\u0051\u0075\u0079\u0044\u002b\u003a\u0063\u0070\u0034\u0033\u0024\u0076\u0077\u0028\u0044\u0039\u006a\u0073\u0070\u0028\u0050\u0029\u0071\u0039\u006a\u005b\u0032\u0041\u0051\u0047\u0059\u0049\u005f\u006f\u005f\u0040\u0023\u002e\u0044\u0067\u0045\u0034\u006b\u0053\u007c\u0046\u002e\u0075\u0023\u0077\u0045\u006c\u002c\u0039\u0070\u0022\u0074\u0047\u002e\u0025\u0045\u0023\u004b\u0061\u0070\u0052\u002e\u0026\u005a\u0043\u0070\u0071\u0051\u0034\u004f\u006c\u004d\u0039\u0043\u0028\u0077\u0068\u0065\u0061\u004d\u0031\u004d\u0043\u0029\u0060\u0033\u006d\u0058\u002b\u0066\u004d\u0060\u0032\u0070\u0058\u0036\u006d\u004f\u0038\u005e\u0077\u0068\u0051\u0034\u004f\u006c\u004d\u0039\u0043\u002e\u0037\u002f\u0046\u005d\u0036\u004f\u0048\u0059\u002a\u006f\u0023\u0075\u0066\u003a\u005e\u0079\u0032\u0061\u0046\u002c\u0053\u002c\u0050\u006b\u0063\u0067\u0022\u0078\u0030\u0052\u0078\u006d\u0038\u004b\u006d\u007a\u0071\u0036\u003c\u0040\u0045\u0061\u0046\u005d\u0070\u0071\u0067\u0050\u005d\u0026\u007c\u0041\u004b\u006d\u007a\u0071\u0036\u003c\u0047\u0043\u006e\u0028\u0061\u006a\u0078\u004a\u0063\u0023\u0029\u007c\u0057\u004c\u006e\u006e\u0024\u002f\u0025\u002c\u0050\u006b\u0063\u0067\u0022\u0071\u007c\u0066\u007b\u004d\u0064\u003e\u0025\u002f\u0021\u0044\u005b\u0026\u0053\u0058\u005f\u0067\u0023\u0022\u0068\u007c\u004d\u007b\u003f\u0060\u0061\u006a\u005f\u0067\u0068\u005e\u003a\u002c\u0050\u006b\u0063\u0067\u0022\u0078\u0030\u0051\u0038\u005f\u005e\u004b\u0031\u0072\u0071\u0033\u0029\u004f\u0071\u004e\u0048\u0048\u0039\u0021\u0062\u0059\u0025\u0073\u003d\u0046\u0068\u0078\u004a\u0062\u0054\u0070\u007c\u0041\u0024\u0043\u006a\u007a\u0025\u0062\u0054\u0070\u007c\u005f\u005f\u0036\u005d\u0052\u0035\u006d\u0045\u007a\u0022\u0022\u0034\u0076\u002a\u0056\u003a\u007b\u0074\u0035\u0036\u0061\u0047\u003c\u005b\u006e\u004f\u0042\u004d\u0055\u0043\u003e\u0072\u0032\u002a\u0053\u0051\u0050\u002a\u0025\u0079\u0030\u003f\u0056\u005e\u0047\u002c\u0034\u0030\u0067\u0057\u0064\u0062\u0029\u005a\u0075\u007b\u003a\u0038\u0046\u003a\u0042\u002b\u002b\u007d\u0075\u0029\u003e\u003e\u0050\u002a\u007e\u006e\u0022\u0075\u007d\u0076\u0023\u0042\u0037\u0063\u002c\u0033\u0036\u0079\u006e\u002a\u0072\u006b\u0023\u0033\u0077\u0076\u0046\u0028\u0072\u0073\u003f\u005e\u0026\u0061\u0057\u003c\u0044\u003d\u0048\u0045\u0044\u0036\u003a\u004a\u0047\u005e\u006f\u0022\u004b\u0062\u006b\u005e\u0028\u0032\u0077\u0028\u0070\u0076\u0021\u0033\u006c\u002b\u0030\u0066\u002b\u0034\u005d\u0050\u0063\u002f\u004f\u006e\u0030\u002a\u0033\u005d\u0034\u003c\u002c\u0050\u0028\u0033\u0048\u005f\u0057\u004d\u007a\u0041\u0062\u0074\u0031\u0039\u0066\u0062\u006d\u0036\u0036\u0035\u0044\u007c\u0057\u0030\u002c\u006f\u0022\u0030\u004f\u003e\u002c\u006b\u0035\u005b\u003c\u0035\u0030\u003c\u0057\u0030\u006e\u004e\u004b\u0048\u004f\u007b\u0021\u003f\u0024\u0026\u0070\u0035\u006d\u0054\u0035\u0057\u0031\u007b\u0053\u0025\u0039\u0028\u0044\u0038\u0068\u0057\u0040\u0025\u0074\u004d\u004d\u0071\u003a\u006a\u005b\u004b\u002e\u0021\u003d\u0042\u0021\u005a\u0076\u0039\u002b\u0024\u0045\u0048\u0040\u0032\u0042\u0068\u003b\u004e\u007d\u002f\u006f\u0068\u002e\u0034\u005b\u0063\u0030\u0023\u0033\u0052\u0076\u0049\u0045\u006d\u0021\u0055\u0073\u004c\u0039\u0062\u0052\u004b\u003d\u0059\u006b\u005d\u006f\u0049\u0060\u0028\u0060\u0033\u007a\u0076\u007e\u002a\u007a\u005e\u0045\u0060\u003b\u003e\u003d\u0034\u0052\u004a\u002b\u003b\u007c\u0079\u004a\u0024\u0058\u0057\u0038\u0024\u0028\u007d\u0044\u0071\u005a\u0066\u0062\u007a\u0074\u0063\u0030\u0029\u0056\u004b\u004a\u0038\u0070\u005e\u0064\u0064\u0028\u0040\u005b\u0067\u0035\u006f\u0071\u003d\u0041\u0056\u0052\u0070\u004c\u003a\u0052\u0024\u0051\u0043\u006f\u0051\u0048\u0068\u0042\u0033\u0067\u0058\u003a\u0059\u0078\u0036\u003b\u006b\u0067\u0060\u0042\u0076\u0039\u005d\u0048\u002b\u006f\u0022\u0040\u003f\u003d\u0033\u005f\u0076\u002b\u0035\u003e\u004b\u0078\u0071\u0063\u0038\u0069\u0054\u0042\u0062\u0070\u0035\u005d\u0043\u0053\u0077\u0037\u0026\u0055\u0026\u0025\u005a\u005a\u006a\u0035\u0046\u003a\u004c\u0065\u0050\u007d\u0069\u0022\u0038\u0060\u0078\u0049\u0076\u007d\u006a\u0066\u0054\u0032\u0037\u007e\u0034\u0049\u0072\u005b\u006a\u0035\u007c\u0073\u0070\u006f\u002b\u004a\u0059\u0075\u003f\u0043\u0076\u005b\u0060\u0022\u0065\u0045\u0050\u0071\u0023\u006f\u007d\u005a\u0045\u007a\u0041\u005d\u0059\u005d\u0063\u0056\u004f\u0077\u0025\u0066\u0036\u0049\u003b\u006e\u006a\u0048\u003f\u0040\u003d\u0044\u005f\u0064\u0039\u004c\u0075\u007e\u002b\u004f\u0031\u004d\u0029\u0078\u0062\u003d\u0068\u007c\u004b\u006d\u0070\u003e\u004e\u0067\u0072\u007e\u005a\u003d\u0028\u003f\u0049\u0069\u0071\u0032\u0036\u002a\u003a\u0026\u007b\u007d\u0078\u0030\u004f\u0048\u005b\u0055\u0042\u0063\u005d\u007a\u0021\u002b\u003a\u0065\u003c\u005d\u0029\u005a\u0073\u0075\u0069\u0040\u0035\u004a\u004a\u0073\u0052\u0059\u005b\u0072\u0037\u006b\u0036\u0069\u0054\u006d\u0026\u0048\u0038\u0073\u004e\u002b\u0064\u005e\u005a\u003e\u0062\u0058\u006f\u0044\u004d\u0037\u0079\u0054\u002e\u0033\u007e\u0064\u0060\u0075\u004c\u0024\u0078\u003d\u0061\u0029\u0077\u0021\u005a\u0062\u002c\u003e\u0071\u0049\u0064\u0035\u0058\u007b\u002a\u003e\u0076\u0050\u0028\u0031\u0071\u0047\u0077\u0046\u0033\u002b\u0045\u0073\u0057\u0053\u0070\u0062\u0055\u0037\u003c\u007b\u004f\u004a\u0069\u0022\u003b\u0045\u002e\u005b\u0038\u0059\u005f\u002f\u0061\u0043\u006b\u0028\u003f\u0070\u006f\u002b\u004a\u0059\u0075\u003f\u0043\u006d\u0061\u0026\u0032\u004a\u005d\u0048\u0047\u0067\u0071\u002b\u0051\u004a\u0062\u0056\u0043\u0075\u0070\u0061\u0022\u0070\u0078\u0047\u0054\u0021\u0063\u0023\u0022\u0033\u0041\u006a\u0069\u0035\u003c\u0035\u0061\u0077\u0025\u0032\u0040\u0051\u005d\u004f\u0049\u002a\u0062\u0036\u005f\u005f\u005f\u0038\u006d\u0055\u0063\u0071\u003e\u0055\u0032\u006d\u0037\u0035\u0045\u0034\u002b\u0049\u0062\u0074\u003e\u0034\u0030\u0053\u004f\u0029\u0022\u0066\u0047\u0032\u002a\u007b\u0064\u0040\u006d\u0072\u0075\u0046\u0026\u0025\u0062\u0024\u0036\u0039\u0066\u0066\u0023\u0032\u003e\u006c\u003c\u0055\u0030\u006c\u007b\u006e\u003c\u006d\u0036\u0038\u005a\u0060\u0032\u0062\u0037\u006c\u0075\u0055\u0021\u0054\u004f\u002e\u005f\u005f\u005d\u0035\u0067\u0021\u0062\u0040\u005b\u0028\u0023\u0072\u0052\u0052\u006f\u006b\u004e\u002a\u0061\u002c\u0026\u0077\u002e\u006e\u0054\u0025\u0036\u0038\u0072\u0024\u0034\u0032\u0047\u0066\u003e\u0079\u0065\u0048\u0055\u0031\u0056\u0051\u005a\u0038\u0045\u0072\u004f\u0064\u0028\u004f\u0078\u0068\u0040\u0029\u0037\u0022\u0034\u0029\u0044\u003b\u0055\u0074\u005a\u006f\u0054\u0028\u0042\u0048\u0065\u006e\u0025\u0071\u0037\u0035\u0029\u0050\u006b\u0052\u0055\u006f\u0058\u0077\u0029\u0045\u0046\u0047\u005d\u0035\u0036\u0029\u002a\u0049\u0070\u0068\u0046\u007a\u0073\u0060\u0033\u007a\u0076\u007e\u002a\u0039\u0023\u0075\u005e\u0071\u004e\u0035\u0070\u0045\u0026\u0073\u005f\u0021\u0033\u006c\u002b\u0030\u0066\u004b\u002e\u004a\u0052\u0079\u007d\u0028\u0047\u006f\u003e\u0061\u005b\u0053\u0038\u006c\u007a\u0030\u0025\u0058\u0077\u0045\u0052\u0054\u005d\u005b\u0033\u0071\u0074\u005b\u006c\u0074\u0069\u0068\u0046\u0046\u0022\u0065\u0048\u006e\u0059\u0064\u0056\u003c\u0048\u003d\u0031\u006b\u0061\u0025\u0070\u007e\u0068\u0063\u0066\u0046\u0042\u0035\u0037\u0067\u004b\u0048\u0056\u0054\u0041\u0045\u006b\u002a\u006e\u0063\u0055\u0046\u0042\u0035\u002f\u0067\u0061\u003c\u002c\u0075\u0052\u0033\u005d\u0031\u0069\u005b\u004f\u0063\u0076\u003b\u004a\u0037\u003b\u007a\u0063\u0061\u002f\u007c\u003a\u004a\u0026\u0039\u005d\u0050\u0035\u0062\u0025\u002a\u0070\u005d\u003f\u0022\u0023\u005d\u0040\u005e\u002e\u0042\u007e\u0067\u0050\u0072\u007d\u007a\u0032\u003c\u0046\u0051\u0061\u0034\u002a\u0025\u0065\u007d\u005e\u0044\u0052\u0031\u007a\u005d\u004e\u0049\u0026\u007a\u006d\u0042\u004e\u0056\u0043\u0054\u0039\u0047\u0062\u0064\u0071\u0058\u004c\u0031\u004d\u006e\u0051\u002b\u0050\u003c\u0049\u0057\u006c\u002c\u002e\u0076\u0066\u0051\u002b\u0050\u003c\u0029\u0051\u003b\u006c\u005e\u0079\u0064\u0047\u0031\u0030\u0060\u0021\u0040\u004a\u0054\u0039\u0069\u0061\u007d\u0042\u003c\u0079\u006b\u0066\u0052\u006c\u004f\u0025\u0079\u0034\u0040\u006b\u0034\u0055\u0023\u0035\u0030\u0051\u0069\u0028\u0075\u0067\u006e\u0042\u0026\u007d\u007a\u0041\u004a\u004f\u0032\u003d\u0078\u0066\u0069\u004b\u0054\u0077\u0065\u005d\u0039\u004b\u003d\u006c\u007d\u003f\u003b\u0078\u0066\u0069\u004b\u0054\u0077\u0041\u0050\u0071\u0046\u0062\u0034\u0029\u004e\u0047\u0079\u0042\u0040\u0068\u0056\u007a\u005a\u0028\u007e\u0025\u0075\u0047\u003d\u0037\u0058\u002c\u0051\u0057\u0057\u005d\u0025\u0069\u004b\u005b\u003b\u002a\u0021\u005e\u006d\u003c\u002a\u006e\u0023\u002b\u0061\u0044\u0037\u006f\u007c\u0054\u0033\u0062\u007e\u0039\u0059\u0078\u0052\u0053\u0052\u006b\u0041\u0032\u0032\u0025\u0028\u0068\u002a\u0059\u0077\u007b\u0053\u004c\u0032\u003f\u007a\u0046\u004b\u0050\u003c\u003e\u0079\u006a\u0039\u005e\u0052\u0046\u0042\u0075\u0062\u004a\u002c\u002e\u0030\u0063\u003c\u005a\u0040\u003d\u003c\u0047\u004a\u0074\u0058\u0078\u0052\u0053\u0052\u005b\u0041\u0057\u0065\u005a\u0040\u0046\u003c\u0021\u0033\u0068\u0065\u0070\u003e\u0035\u004f\u0071\u0065\u0054\u0047\u0069\u004c\u005f\u002f\u005b\u007d\u005a\u0053\u006e\u0043\u007e\u007b\u006a\u005d\u002e\u0023\u0033\u007d\u004a\u0068\u0047\u0021\u006f\u0040\u004c\u007d\u0026\u004a\u0067\u0021\u0024\u0066\u0077\u0036\u002f\u0055\u006b\u0059\u006f\u0040\u0032\u0075\u0061\u004a\u0023\u0024\u002a\u0053\u0037\u006a\u004f\u006e\u0021\u004d\u002c\u0074\u005b\u0045\u004f\u0053\u0040\u002f\u005d\u0038\u0048\u0024\u0073\u0068\u0035\u0057\u0034\u0040\u0062\u003c\u0047\u004a\u0050\u0058\u0078\u0052\u0037\u0052\u002e\u004e\u0032\u0032\u0055\u002e\u002b\u0043\u005f\u004f\u0046\u003d\u0029\u007a\u0049\u0036\u004e\u0063\u0021\u004d\u002c\u0074\u005b\u0045\u004f\u0053\u0040\u002f\u005d\u0038\u0048\u0024\u0073\u0068\u0035\u0057\u0034\u0040\u0062\u003c\u0047\u004a\u0050\u0058\u0078\u0052\u0037\u0052\u002e\u004e\u0032\u0032\u005b\u0060\u0047\u0079\u0029\u006c\u0059\u0040\u0047\u004a\u006a\u0072\u0078\u0052\u0053\u0052\u006b\u0041\u0032\u0032\u0025\u0028\u0068\u002a\u0077\u006c\u0068\u004a\u0028\u004f\u0035\u0031\u0041\u0049\u0052\u0060\u0043\u003b\u0056\u0042\u0061\u004d\u0024\u0070\u0049\u0045\u005f\u0053\u006c\u0032\u0025\u0028\u002b\u0043\u0072\u007a\u006f\u006c\u0060\u002b\u005e\u006b\u0022\u007c\u0047\u004a\u0061\u002a\u0069\u0069\u002f\u0035\u0048\u0039\u0067\u002b\u006c\u0074\u0022\u0040\u0041\u004b\u002f\u0061\u0063\u006e\u0031\u0048\u0051\u005a\u0023\u003d\u0053\u0078\u0047\u004a\u0061\u002a\u007a\u0038\u0071\u005d\u002a\u0077\u0029\u0063\u003e\u0072\u0064\u005e\u0078\u0023\u0064\u006e\u0052\u0048\u005d\u007a\u002f\u004b\u005b\u004c\u006c\u002a\u007d\u0079\u0043\u007d\u0041\u0051\u0037\u002c\u0046\u0021\u0057\u007a\u004f\u0054\u0029\u002c\u0046\u0021\u0057\u0047\u004a\u0028\u004a\u0078\u0052\u0053\u0052\u006b\u0041\u0032\u0032\u0025\u0028\u002b\u0043\u0072\u007a\u0046\u003d\u0068\u0033\u0047\u004a\u0074\u0058\u0078\u0052\u0053\u0052\u006b\u0041\u0032\u0032\u0025\u0028\u002b\u0043\u0072\u007a\u0046\u003d\u0068\u0033\u0047\u004a\u0074\u0058